package app.kivo.store;
import org.json.*;import java.util.*;import java.io.*;
public class TranslationReviewsTest{
 static void check(boolean b,String message){if(!b)throw new AssertionError(message);}
 public static void main(String[] args)throws Exception{
 for(String text:Arrays.asList("Hello world. "+String.join("",Collections.nCopies(800,"a")),String.join("",Collections.nCopies(400,"中文😀 á test. ")))){List<String> chunks=TranslationText.chunks(text,480);StringBuilder combined=new StringBuilder();for(String part:chunks){check(part.getBytes("UTF-8").length<=480,"UTF8 bytes exceed provider limit");check(!Character.isLowSurrogate(part.charAt(0)),"Split surrogate at start");check(!Character.isHighSurrogate(part.charAt(part.length()-1)),"Split surrogate at end");combined.append(part);}check(text.equals(combined.toString()),"Chunking must preserve input");}
 check(TranslationText.limit("😀😀x",2).equals("😀😀"),"Character cap must preserve emoji");check(TranslationText.response(new JSONObject("{\"responseStatus\":200,\"responseData\":{\"translatedText\":\"Hola\"}}")).equals("Hola"),"Successful provider response");for(String value:Arrays.asList("{\"responseStatus\":429}","{\"responseStatus\":200,\"quotaFinished\":true}","{\"responseStatus\":403}","{\"responseStatus\":200,\"responseData\":{\"translatedText\":\"\"}}"))try{TranslationText.response(new JSONObject(value));throw new AssertionError("Provider error accepted");}catch(IOException expected){}
 JSONArray verified=new JSONArray().put(new JSONObject().put("repo","github/first").put("package","org.example.app").put("signer","abc"));check(ReviewEligibility.allows("org.example.app","abc",verified),"Verified package qualifies across source rows");check(!ReviewEligibility.allows("org.other.app","abc",verified),"Same certificate on other package cannot qualify");check(!ReviewEligibility.allows("org.example.app","other",verified),"Different actual certificate cannot qualify");check(!ReviewEligibility.allows("org.example.app","",verified),"Unknown actual certificate cannot qualify");check(!ReviewEligibility.allows("org.example.app","abc",new JSONArray()),"No verified download cannot qualify");
 System.out.println("PASS: translation UTF8 segmentation/emoji, response and quota errors, exact package/certificate review eligibility across sources.");}
}
